                <div class="mt-7 grid grid-cols-2 border-b border-slate-300"><button type="button" id="ticket-tab-collaborator" onclick="showTicketTab('collaborator')" class="border-b-4 border-red-500 py-3 font-medium text-red-600">Colaborador</button><button type="button" id="ticket-tab-admin" onclick="showTicketTab('admin')" class="border-b-4 border-transparent py-3 font-medium text-slate-500">Administrador</button></div>
