<script>
function togglePasswordVisibility(button){const input=document.getElementById('password');const visible=input.type==='text';input.type=visible?'password':'text';button.setAttribute('aria-label',visible?'Mostrar contrase&ntilde;a':'Ocultar contrase&ntilde;a');}
function flipLoginCard(showTickets){const card=document.getElementById('login-card');if(card)card.style.transform=showTickets?'rotateY(180deg)':'rotateY(0deg)';}
function showTicketTab(tab){const collaborator=tab==='collaborator';document.getElementById('ticket-collaborator-form').classList.toggle('hidden',!collaborator);document.getElementById('ticket-admin-form').classList.toggle('hidden',collaborator);document.getElementById('ticket-tab-collaborator').className=collaborator?'border-b-4 border-red-500 py-3 font-medium text-red-600':'border-b-4 border-transparent py-3 font-medium text-slate-500';document.getElementById('ticket-tab-admin').className=!collaborator?'border-b-4 border-red-500 py-3 font-medium text-red-600':'border-b-4 border-transparent py-3 font-medium text-slate-500';}
function toggleTicketPassword(button){const input=document.getElementById('ticket-password');const visible=input.type==='text';input.type=visible?'password':'text';button.setAttribute('aria-label',visible?'Mostrar contraseña':'Ocultar contraseña');}
async function loginTickets(event,type){event.preventDefault();const error=document.getElementById('ticket-login-error');error.classList.add('hidden');const payload=type==='collaborator'?{department:document.getElementById('ticket-department').value}:{username:document.getElementById('ticket-username').value,password:document.getElementById('ticket-password').value};const action=type==='collaborator'?'login-collaborator':'login-admin';try{const response=await fetch('/tickets/api/auth.php?action='+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(data.success){window.location.href='/tickets/index.php?page=dashboard';}else{error.textContent=data.error||'No fue posible iniciar sesi&oacute;n';error.classList.remove('hidden');}}catch(e){error.textContent='No fue posible conectar con el sistema de tickets.';error.classList.remove('hidden');}}
</script>
